def group_states(grid, goal):
    # Initialize a dictionary to store the groups
    groups = {}

    # Iterate over each state in the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != "X":
                # Check all neighboring states and group them together
                group = set()
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if (x, y) not in group:
                        group.add((x, y))
                        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nx, ny = x + dx, y + dy
                            if (nx, ny) != (goal, goal) and (0 <= nx < len(grid)) and (0 <= ny < len(grid[0])) and grid[nx][ny] != "X":
                                stack.append((nx, ny))
                # Add the group to the dictionary
                groups[(i, j)] = list(group)

    return list(groups.values())

